from django.db import migrations, models


def copy_legacy_adjustments(apps, schema_editor):
    """把旧 run 行里的调参流水逐条转成 DetectorTuneLog（只增不删，可重复执行）。"""
    DetectorRun = apps.get_model('stocks', 'DetectorRun')
    DetectorTuneLog = apps.get_model('stocks', 'DetectorTuneLog')
    rows = []
    for run in DetectorRun.objects.exclude(adjustments=[]).only('trade_date', 'adjustments'):
        if DetectorTuneLog.objects.filter(trade_date=run.trade_date, source='legacy').exists():
            continue
        for entry in run.adjustments or []:
            if not isinstance(entry, dict) or not entry.get('dim'):
                continue
            changes = {}
            if entry.get('from_weight') != entry.get('to_weight'):
                changes['weight'] = [entry.get('from_weight'), entry.get('to_weight')]
            if entry.get('from_min') != entry.get('to_min'):
                changes['min'] = [entry.get('from_min'), entry.get('to_min')]
            rows.append(DetectorTuneLog(
                trade_date=run.trade_date,
                dim_key=str(entry['dim'])[:40],
                source='legacy',
                applied=True,
                changes=changes,
                stats={k: entry.get(k) for k in ('samples', 'hit_rate', 'baseline', 'excess')},
                reason=str(entry.get('reason') or '')[:300],
            ))
    DetectorTuneLog.objects.bulk_create(rows, batch_size=500)


